package com.flightparty.table;
import java.util.*;
/** Casual shared-target pool. Physics and pockets are simulated on the server.
 * Command = spot * 363600 + power * 3600 + angle. Spot 0 preserves legacy center hits;
 * 1..8 run clockwise from top: follow, follow-right, right, draw-right, draw, draw-left,
 * left, follow-left. Spin is a bounded arcade approximation, not a rigid-body model. */
public final class PoolRules {
 private static final double[][] HOLES={{0,0},{500,0},{1000,0},{0,500},{500,500},{1000,500}};
 public static GridRules.State start(){int[] c=new int[29];c[0]=2500;c[1]=2500;c[2]=1;int n=1;for(int col=0;col<4&&n<9;col++)for(int row=0;row<=col&&n<9;row++,n++){c[n*3]=6500+col*215;c[n*3+1]=2500+(int)Math.round((row-col*.5)*250);c[n*3+2]=1;}return new GridRules.State("pool",c,1,0,false,0,"",List.of());}
 public static GridRules.State move(GridRules.State s,int actor,int command){if(s.over()||actor!=s.turn())throw new IllegalStateException();int spinCode=command/363600,shot=command%363600,power=shot/3600,angle=shot%3600;if(command<0||spinCode>8||power<1||power>100)throw new IllegalArgumentException();double q=Math.sqrt(.5),side=new double[]{0,0,q,1,q,0,-q,-1,-q}[spinCode],follow=new double[]{0,1,q,0,-q,-1,-q,0,q}[spinCode],ax=Math.cos(angle*Math.PI/1800),ay=Math.sin(angle*Math.PI/1800),spinLife=1;boolean contactSpin=false;double[] x=new double[9],y=new double[9],vx=new double[9],vy=new double[9];boolean[] alive=new boolean[9];int[] c=s.cells().clone();for(int i=0;i<9;i++){x[i]=c[i*3]/10.;y[i]=c[i*3+1]/10.;alive[i]=c[i*3+2]==1;}vx[0]=Math.cos(angle*Math.PI/1800)*power*.16;vy[0]=Math.sin(angle*Math.PI/1800)*power*.16;var frames=new ArrayList<String>();int pocket=0;boolean scratch=false,black=false;
 for(int step=0;step<1200;step++){double speed=0;for(int i=0;i<9;i++)if(alive[i]){x[i]+=vx[i];y[i]+=vy[i];boolean sink=false;for(var h:HOLES)if(Math.hypot(x[i]-h[0],y[i]-h[1])<27)sink=true;if(sink){alive[i]=false;vx[i]=vy[i]=0;if(i==0)scratch=true;else if(i==8)black=true;else pocket++;continue;}if(x[i]<12||x[i]>988){x[i]=Math.max(12,Math.min(988,x[i]));vx[i]*=-.92;if(i==0&&side!=0){double magnitude=Math.hypot(vx[i],vy[i]);vy[i]+=Math.abs(vx[i])*side*.18*spinLife;double scale=magnitude/Math.hypot(vx[i],vy[i]);vx[i]*=scale;vy[i]*=scale;}}if(y[i]<12||y[i]>488){y[i]=Math.max(12,Math.min(488,y[i]));vy[i]*=-.92;if(i==0&&side!=0){double magnitude=Math.hypot(vx[i],vy[i]);vx[i]-=Math.abs(vy[i])*side*.18*spinLife;double scale=magnitude/Math.hypot(vx[i],vy[i]);vx[i]*=scale;vy[i]*=scale;}}vx[i]*=.985;vy[i]*=.985;if(Math.hypot(vx[i],vy[i])<.035)vx[i]=vy[i]=0;speed+=Math.hypot(vx[i],vy[i]);}
 for(int i=0;i<9;i++)for(int j=i+1;j<9;j++)if(alive[i]&&alive[j]){double dx=x[j]-x[i],dy=y[j]-y[i],d=Math.hypot(dx,dy);if(d>0&&d<24){double nx=dx/d,ny=dy/d,overlap=(24-d)/2;x[i]-=nx*overlap;y[i]-=ny*overlap;x[j]+=nx*overlap;y[j]+=ny*overlap;double impulse=(vx[i]-vx[j])*nx+(vy[i]-vy[j])*ny;if(impulse>0){vx[i]-=impulse*nx;vy[i]-=impulse*ny;vx[j]+=impulse*nx;vy[j]+=impulse*ny;if(i==0&&!contactSpin&&spinCode!=0){double forward=power*.035*follow*spinLife,lateral=power*.018*side*spinLife;vx[0]+=ax*forward-ay*lateral;vy[0]+=ay*forward+ax*lateral;contactSpin=true;}}}}
 spinLife*=.997;if(step%25==0&&frames.size()<48)frames.add(frame(x,y,alive));if(speed<.04&&step>1)break;}
 if(scratch){alive[0]=true;outer:for(int xx=180;xx<=420;xx+=30)for(int yy=80;yy<450;yy+=30){boolean free=true;for(int i=1;i<9;i++)if(alive[i]&&Math.hypot(xx-x[i],yy-y[i])<27)free=false;if(free){x[0]=xx;y[0]=yy;break outer;}}}
 for(int i=0;i<9;i++){c[i*3]=(int)Math.round(x[i]*10);c[i*3+1]=(int)Math.round(y[i]*10);c[i*3+2]=alive[i]?1:0;}c[26+actor]+=pocket;boolean remaining=false;for(int i=1;i<8;i++)if(alive[i])remaining=true;boolean over=black||s.moves()+1>=200;int winner=black?(scratch||remaining?3-actor:actor):over?(c[27]==c[28]?0:c[27]>c[28]?1:2):0;frames.add(frame(x,y,alive));return new GridRules.State("pool",c,pocket>0&&!scratch?actor:3-actor,winner,over,s.moves()+1,scratch?"白球落袋，换手并复位":black?"8号球落袋":"本杆落袋 "+pocket+" 颗",frames);}
 private static String frame(double[] x,double[]y,boolean[]alive){var p=new ArrayList<String>();for(int i=0;i<9;i++){p.add(""+Math.round(x[i]*10));p.add(""+Math.round(y[i]*10));p.add(alive[i]?"1":"0");}return String.join(",",p);}
 public static int bot(GridRules.State s){int[] c=s.cells();int target=8;double best=Double.MAX_VALUE;for(int i=1;i<8;i++)if(c[i*3+2]==1){double distance=Math.hypot(c[i*3]-c[0],c[i*3+1]-c[1]);if(distance<best){target=i;best=distance;}}double angle=Math.atan2(c[target*3+1]-c[1],c[target*3]-c[0]);int a=((int)Math.round(angle*1800/Math.PI)+3600)%3600;return 75*3600+a;}
}
